insert into public.ascend_questions (id, subject, level, domain, skill, passage, data_table, question, choices, answer_index, accept, explanation, status, source, published_at) values
('mathl2c_001', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 5(2x + 1) − 3x = 26, what is the value of x?', '["2.1", "3", "4", "21/13"]'::jsonb, 1, null, 'Distribute: 10x + 5 − 3x = 26, so 7x = 21 and x = 3.', 'published', 'import', now()),
('mathl2c_002', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 2.5x − 4 = 1.5x + 7, what is the value of x?', null, null, '["11"]'::jsonb, 'Subtract 1.5x: x − 4 = 7, so x = 11.', 'published', 'import', now()),
('mathl2c_003', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'If 4x + 9 = 33, what is the value of 2x + 1?', '["6", "13", "12", "25"]'::jsonb, 1, null, '4x = 24, so x = 6 and 2x + 1 = 13.', 'published', 'import', now()),
('mathl2c_004', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'For what value of c does 3(x − c) = 3x − 12 have infinitely many solutions?', '["12", "−4", "3", "4"]'::jsonb, 3, null, '3x − 3c = 3x − 12 for every x when 3c = 12, so c = 4.', 'published', 'import', now()),
('mathl2c_005', 'math', 2, 'Algebra', 'Linear equations in one variable', null, null, 'A plumber earns $65 per hour and pays $40 for parts on a job. She earns a profit of $350. How many hours did she work?', '["6.6", "5.4", "6", "5"]'::jsonb, 2, null, '65h − 40 = 350, so 65h = 390 and h = 6.', 'published', 'import', now()),
('mathl2c_006', 'math', 2, 'Algebra', 'Linear functions', null, null, 'Line p passes through (−1, 7) and (3, −5). What is the y-intercept of line p?', null, null, '["4"]'::jsonb, 'The slope is (−5 − 7) ÷ (3 + 1) = −3. Then 7 = −3(−1) + b, so b = 4.', 'published', 'import', now()),
('mathl2c_007', 'math', 2, 'Algebra', 'Linear functions', null, null, 'The equation W = 1,500 − 75t gives the water W, in liters, left in a pool t hours after it starts draining. How many hours does it take to drain completely?', '["20", "15", "75", "1,425"]'::jsonb, 0, null, 'Set W = 0: 75t = 1,500, so t = 20.', 'published', 'import', now()),
('mathl2c_008', 'math', 2, 'Algebra', 'Linear functions', null, null, 'Which equation represents the line through (2, 9) with slope −4?', '["y = −4x + 1", "y = −4x + 9", "y = 4x + 1", "y = −4x + 17"]'::jsonb, 3, null, '9 = −4(2) + b, so b = 17.', 'published', 'import', now()),
('mathl2c_009', 'math', 2, 'Algebra', 'Linear functions', null, null, 'In the xy-plane, the line 3x + 4y = 24 crosses the x-axis at which point?', '["(8, 0)", "(24, 0)", "(0, 6)", "(6, 0)"]'::jsonb, 0, null, 'On the x-axis, y = 0, so 3x = 24 and x = 8.', 'published', 'import', now()),
('mathl2c_010', 'math', 2, 'Algebra', 'Linear functions', null, null, 'A gym membership costs $35 per month after a one-time fee of $50. Which function gives the total cost C after m months?', '["C(m) = 85m", "C(m) = 50m + 35", "C(m) = 35m + 50", "C(m) = 35(m + 50)"]'::jsonb, 2, null, 'The one-time fee is 50 and each month adds 35.', 'published', 'import', now()),
('mathl2c_011', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, '2x + 5y = 1
x − 2y = 5

What is the value of y?', '["−1", "3", "1", "−3"]'::jsonb, 0, null, 'x = 2y + 5. Then 2(2y + 5) + 5y = 1, so 9y = −9 and y = −1.', 'published', 'import', now()),
('mathl2c_012', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'A shop sells muffins for $3 and bagels for $2. Rina buys 12 items and spends $31. How many muffins does she buy?', null, null, '["7"]'::jsonb, 'm + b = 12 and 3m + 2b = 31. Then 3m + 24 − 2m = 31, so m = 7.', 'published', 'import', now()),
('mathl2c_013', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'For which value of k does the system have no solution?

y = kx + 2
y = 5x − 3', '["2", "5", "−3", "−5"]'::jsonb, 1, null, 'Lines with the same slope and different intercepts never meet, so k = 5.', 'published', 'import', now()),
('mathl2c_014', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, 'x + y = 18
y = x + 4

What is the value of xy?', '["80", "11", "77", "7"]'::jsonb, 2, null, 'x + x + 4 = 18, so x = 7 and y = 11. xy = 77.', 'published', 'import', now()),
('mathl2c_015', 'math', 2, 'Algebra', 'Linear inequalities', null, null, 'Which point is in the solution set of y < −2x + 5?', '["(0, 6)", "(2, 3)", "(1, 2)", "(3, 0)"]'::jsonb, 2, null, 'For (1, 2): −2(1) + 5 = 3, and 2 < 3 is true. Each other point fails.', 'published', 'import', now()),
('mathl2c_016', 'math', 2, 'Algebra', 'Linear inequalities', null, null, 'A group has $150 to spend at a museum. They must pay an $18 parking fee, and tickets cost $12 each. What is the greatest number of tickets they can buy?', null, null, '["11"]'::jsonb, '18 + 12t ≤ 150, so 12t ≤ 132 and t ≤ 11.', 'published', 'import', now()),
('mathl2c_017', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (3x + 2)(x − 4)?', '["3x^{2} + 10x − 8", "3x^{2} − 14x − 8", "3x^{2} − 8", "3x^{2} − 10x − 8"]'::jsonb, 3, null, '3x^{2} − 12x + 2x − 8 = 3x^{2} − 10x − 8.', 'published', 'import', now()),
('mathl2c_018', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is a factored form of x^{2} + 2x − 24?', '["(x + 6)(x − 4)", "(x + 8)(x − 3)", "(x − 6)(x + 4)", "(x + 12)(x − 2)"]'::jsonb, 0, null, 'Two numbers that multiply to −24 and add to 2 are 6 and −4.', 'published', 'import', now()),
('mathl2c_019', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{5})(x^{−2})?', '["x^{3}", "x^{2.5}", "x^{−10}", "x^{7}"]'::jsonb, 0, null, 'Add exponents: 5 + (−2) = 3.', 'published', 'import', now()),
('mathl2c_020', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 2(x^{2} − 3x) − (x^{2} + x − 5)?', '["3x^{2} − 7x + 5", "x^{2} − 5x − 5", "x^{2} − 7x + 5", "x^{2} − 7x − 5"]'::jsonb, 2, null, '2x^{2} − 6x − x^{2} − x + 5 = x^{2} − 7x + 5.', 'published', 'import', now()),
('mathl2c_021', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the positive solution to 2x^{2} − 50 = 0?', null, null, '["5"]'::jsonb, '2x^{2} = 50, so x^{2} = 25 and x = 5.', 'published', 'import', now()),
('mathl2c_022', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If 5^{2x} = 625, what is the value of x?', '["2", "5", "4", "125"]'::jsonb, 0, null, '625 = 5^{4}, so 2x = 4 and x = 2.', 'published', 'import', now()),
('mathl2c_023', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'What are the solutions to x^{2} = 6x?', '["x = 6 only", "x = 0 and x = 6", "x = −6 and x = 6", "x = 0 and x = −6"]'::jsonb, 1, null, 'x^{2} − 6x = 0, so x(x − 6) = 0 and x = 0 or 6.', 'published', 'import', now()),
('mathl2c_024', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If √x + 3 = 10, what is the value of x?', '["7", "100", "49", "13"]'::jsonb, 2, null, '√x = 7, so x = 49.', 'published', 'import', now()),
('mathl2c_025', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = −2x^{2} + 3. What is f(−1)?', '["1", "−5", "−1", "5"]'::jsonb, 0, null, 'f(−1) = −2(1) + 3 = 1.', 'published', 'import', now()),
('mathl2c_026', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'A painting''s value is modeled by V(t) = 800(1.06)^{t}, where t is years after purchase. What was the painting''s value when it was purchased, in dollars?', '["848", "800", "1.06", "6"]'::jsonb, 1, null, 'At purchase, t = 0, and (1.06)^{0} = 1, so V = 800.', 'published', 'import', now()),
('mathl2c_027', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'What are the x-intercepts of the graph of y = (x − 3)(x + 6)?', '["(3, 0) only", "(3, 0) and (−6, 0)", "(−3, 0) and (6, 0)", "(0, 3) and (0, −6)"]'::jsonb, 1, null, 'y = 0 when x = 3 or x = −6.', 'published', 'import', now()),
('mathl2c_028', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'If h(x) = x^{2} − 1 and k(x) = x + 2, what is k(h(3))?', null, null, '["10"]'::jsonb, 'h(3) = 8, and k(8) = 10.', 'published', 'import', now()),
('mathl2c_029', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A faucet leaks 3 milliliters every 10 seconds. How many liters does it leak in one day? (1 liter = 1,000 milliliters)', '["25.92", "2.592", "4.32", "259.2"]'::jsonb, 0, null, 'There are 86,400 seconds in a day, or 8,640 ten-second periods. 8,640 × 3 = 25,920 mL = 25.92 L.', 'published', 'import', now()),
('mathl2c_030', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A recipe for 4 servings uses 300 grams of rice. How many grams of rice are needed for 10 servings?', null, null, '["750"]'::jsonb, '300 ÷ 4 = 75 grams per serving. 75 × 10 = 750.', 'published', 'import', now()),
('mathl2c_031', 'math', 2, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'An exchange rate is 1 US dollar = 0.92 euro. About how many US dollars equal 230 euros?', '["250", "212", "211.60", "230"]'::jsonb, 0, null, '230 ÷ 0.92 = 250 dollars.', 'published', 'import', now()),
('mathl2c_032', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A laptop''s price drops from $900 to $765. By what percent did the price decrease?', '["13.5%", "15%", "17.6%", "135%"]'::jsonb, 1, null, 'The decrease is 135. 135 ÷ 900 = 0.15 = 15%.', 'published', 'import', now()),
('mathl2c_033', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A town''s population of 8,000 increases by 5% each year. What is the population after 2 years?', null, null, '["8820", "8,820"]'::jsonb, '8,000 × 1.05 × 1.05 = 8,820.', 'published', 'import', now()),
('mathl2c_034', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'In a survey, 42 of the 120 students chose science as their favorite subject. What percent chose science?', '["65%", "35%", "28%", "42%"]'::jsonb, 1, null, '42 ÷ 120 = 0.35 = 35%.', 'published', 'import', now()),
('mathl2c_035', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The median of 4, 7, x, 12, and 15 is 9. The numbers are listed from least to greatest. What is x?', '["7", "12", "9", "8"]'::jsonb, 2, null, 'With five numbers in order, the median is the middle value, x. So x = 9.', 'published', 'import', now()),
('mathl2c_036', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A class''s quiz scores have a mean of 82. The teacher adds 3 points to every score. What is the new mean?', '["85", "84.5", "246", "82"]'::jsonb, 0, null, 'Adding the same amount to every value adds that amount to the mean.', 'published', 'import', now()),
('mathl2c_037', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Which data set has the greatest range?', '["20, 24, 25, 30", "10, 11, 12, 13", "5, 9, 13, 17", "3, 8, 14, 22"]'::jsonb, 3, null, 'The ranges are 19, 3, 12, and 10. The first set has the greatest range.', 'published', 'import', now()),
('mathl2c_038', 'math', 2, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'The scatterplot of hours of daylight versus average temperature for a city shows points rising from lower left to upper right. Which describes the association?', '["Negative", "Exactly linear and decreasing", "None", "Positive"]'::jsonb, 3, null, 'When both variables increase together, the association is positive.', 'published', 'import', now()),
('mathl2c_039', 'math', 2, 'Problem-Solving and Data Analysis', 'Two-variable data', null, '{"h": ["Day d", "Sales S"], "r": [["0", "30"], ["1", "42"], ["2", "54"], ["3", "66"]]}'::jsonb, 'The table shows a store''s sales of umbrellas. Which linear function fits the data?', '["S = 42d", "S = 30d + 12", "S = 12d − 30", "S = 12d + 30"]'::jsonb, 3, null, 'Sales increase by 12 each day, starting at 30 on day 0.', 'published', 'import', now()),
('mathl2c_040', 'math', 2, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A class has 14 girls and 16 boys. Half of the girls and a quarter of the boys wear glasses. If a student who wears glasses is chosen at random, what is the probability the student is a girl?', '["1/2", "4/11", "7/11", "7/15"]'::jsonb, 2, null, '7 girls and 4 boys wear glasses, so 11 students in all. P(girl) = 7/11.', 'published', 'import', now()),
('mathl2c_041', 'math', 2, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A bag holds 5 red and 3 yellow balls. Two balls are drawn without replacement. What is the probability both are yellow?', '["3/28", "3/8", "1/4", "9/64"]'::jsonb, 0, null, '(3/8) × (2/7) = 6/56 = 3/28.', 'published', 'import', now()),
('mathl2c_042', 'math', 2, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'In a random sample of 250 households, 90 have a dog. There are 12,000 households in the town. What is the best estimate of the number of households with a dog?', '["9,000", "3,600", "4,500", "4,320"]'::jsonb, 3, null, '90/250 = 36%. 36% of 12,000 = 4,320.', 'published', 'import', now()),
('mathl2c_043', 'math', 2, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A news site asks readers to vote online on whether a new park should be built. Why might the results be unreliable?', '["Online votes are always counted wrong", "The sample is too random", "Parks are not a good survey topic", "The people who chose to vote may not represent all residents"]'::jsonb, 3, null, 'A voluntary-response sample includes only people who choose to respond, so it may be biased.', 'published', 'import', now()),
('mathl2c_044', 'math', 2, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A cylinder has a diameter of 10 and a height of 4. What is its volume?', '["400π", "40π", "20π", "100π"]'::jsonb, 3, null, 'The radius is 5. V = π(25)(4) = 100π.', 'published', 'import', now()),
('mathl2c_045', 'math', 2, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangle has an area of 96 square units and a width of 8 units. What is its perimeter?', null, null, '["40"]'::jsonb, 'Length = 96 ÷ 8 = 12. Perimeter = 2(12 + 8) = 40.', 'published', 'import', now()),
('mathl2c_046', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'In isosceles triangle PQR, PQ = PR and angle P measures 40°. What is the measure of angle Q?', '["140°", "70°", "40°", "50°"]'::jsonb, 1, null, 'Angles Q and R are equal and share 180 − 40 = 140, so each is 70°.', 'published', 'import', now()),
('mathl2c_047', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'A triangle has sides of 6, 8, and x. Which value could be x?', '["2", "10", "14", "1"]'::jsonb, 1, null, 'Each side must be less than the sum of the other two and more than their difference: 2 < x < 14. Only 10 works.', 'published', 'import', now()),
('mathl2c_048', 'math', 2, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In right triangle ABC with right angle C, tan A = 5/12. What is sin A?', '["5/12", "13/5", "5/13", "12/13"]'::jsonb, 2, null, 'With legs 5 and 12, the hypotenuse is 13. sin A = opposite ÷ hypotenuse = 5/13.', 'published', 'import', now()),
('mathl2c_049', 'math', 2, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A ramp rises 3 feet over a horizontal distance of 4 feet. How long is the ramp, in feet?', '["12", "5", "7", "6"]'::jsonb, 1, null, '√(9 + 16) = √25 = 5.', 'published', 'import', now()),
('mathl2c_050', 'math', 2, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has an area of 64π. What is its diameter?', '["64", "32", "16", "8"]'::jsonb, 2, null, 'πr^{2} = 64π gives r = 8, so the diameter is 16.', 'published', 'import', now()),
('mathl2c_051', 'math', 2, 'Geometry and Trigonometry', 'Circles', null, null, 'In a circle with radius 6, an arc has a central angle of 60°. What is the arc''s length?', '["π", "12π", "6π", "2π"]'::jsonb, 3, null, 'The circumference is 12π, and 60° is 1/6 of the circle: 12π ÷ 6 = 2π.', 'published', 'import', now()),
('rwl2c_001', 'rw', 2, 'Craft and Structure', 'Words in Context', 'A single surprising result is rarely enough to change scientific thinking. Before accepting the claim that a common spice slows the growth of certain bacteria, microbiologists waited to see whether other laboratories could ____ the experiment and obtain the same outcome.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["simplify", "dismiss", "publish", "replicate"]'::jsonb, 3, null, 'Other labs repeating the experiment to get the same result is what replicate means.', 'published', 'import', now()),
('rwl2c_002', 'rw', 2, 'Craft and Structure', 'Words in Context', 'My grandmother was famously ____. She reused every envelope, mended her own clothes until they were more patch than fabric, and saved the string from every package that arrived.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["wasteful", "frugal", "generous", "careless"]'::jsonb, 1, null, 'Reusing envelopes and mending clothes shows someone who is careful with money, or frugal.', 'published', 'import', now()),
('rwl2c_003', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Mount Rainier in Washington has not erupted in more than a century, but geologists consider it ____ rather than extinct: magma still lies beneath it, and it could erupt again.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["extinct", "dormant", "erupting", "visible"]'::jsonb, 1, null, 'A volcano that hasn''t erupted recently but could again is dormant (inactive for now).', 'published', 'import', now()),
('rwl2c_004', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The editor returned the student''s 1,500-word article with a single note: make it more ____. Readers of the school newsletter, she explained, want the key facts in about 300 words.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["humorous", "concise", "confusing", "lengthy"]'::jsonb, 1, null, 'The editor wanted the article shorter and to the point, which is what concise means.', 'published', 'import', now()),
('rwl2c_005', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The diplomat''s command of five languages allowed her to negotiate directly with officials in Brazil, Egypt, and Japan without interpreters.', null, 'As used in the text, what does the word "command" most nearly mean?', '["have and use", "control by force", "look down on", "order"]'::jsonb, 0, null, 'The text says she has excellent knowledge of several languages, so "command" means possession of a skill.', 'published', 'import', now()),
('rwl2c_006', 'rw', 2, 'Craft and Structure', 'Words in Context', 'For the Haudenosaunee, the "Three Sisters" (corn, beans, and squash) were ____ to agriculture: the three crops were planted together because each helped the others grow.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["harmful", "integral", "optional", "accidental"]'::jsonb, 1, null, 'Something essential to the whole is integral.', 'published', 'import', now()),
('rwl2c_007', 'rw', 2, 'Craft and Structure', 'Words in Context', 'For centuries, the cave paintings at Lascaux in France survived in darkness. After the cave opened to visitors in 1948, however, the paintings ____ quickly, as moisture from visitors'' breath encouraged the growth of mold.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["disappeared", "multiplied", "improved", "deteriorated"]'::jsonb, 3, null, 'The paintings got worse over time from damp and light, which is what deteriorated means.', 'published', 'import', now()),
('rwl2c_008', 'rw', 2, 'Craft and Structure', 'Words in Context', 'Before a new bridge opens, inspectors ____ every bolt, cable, and weld, looking for even the smallest flaw that could weaken the structure.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["copy", "ignore", "scrutinize", "praise"]'::jsonb, 2, null, 'Examining every detail closely is what scrutinize means.', 'published', 'import', now()),
('rwl2c_009', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'More than two thousand years ago, Persian engineers built yakhchals, dome-shaped buildings that stored ice through hot desert summers. Thick walls of heat-resistant mortar kept the inside cool, and an underground pit trapped cold air. Ice made on winter nights could last well into summer.', null, 'Which choice best states the main purpose of the text?', '["To argue that refrigerators should be replaced", "To explain how ice forms in nature", "To compare ancient and modern deserts", "To describe how an ancient technology kept food cold without electricity"]'::jsonb, 3, null, 'The text explains how Persian yakhchals stored ice in the desert.', 'published', 'import', now()),
('rwl2c_010', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'In 2021, researchers studying an ancient lakebed in New Mexico examined footprints preserved in the hardened mud. Seeds trapped in the layers above and below the prints were dated to between 21,000 and 23,000 years ago. If those dates are correct, people lived in North America thousands of years earlier than many scientists had believed.', null, 'Which choice best describes the function of the third sentence in the overall structure of the text?', '["It explains the significance of the discovery described earlier", "It describes the tools used in the excavation", "It questions whether the discovery happened", "It introduces a new, unrelated discovery"]'::jsonb, 0, null, 'The third sentence tells why the find matters: it pushes back the date of human settlement.', 'published', 'import', now()),
('rwl2c_011', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'By the 1960s, the Cuyahoga River in Ohio was so polluted that its surface sometimes caught fire. Decades of factories had dumped oil and chemicals into the water. After a 1969 fire drew national attention, Congress passed the Clean Water Act in 1972, and the river has since recovered enough to support dozens of fish species.', null, 'Which choice best describes the overall structure of the text?', '["It lists facts about a river in no particular order", "It compares two cities and ranks them", "It introduces a problem, explains its cause, and then describes a response", "It describes a person''s life from birth to death"]'::jsonb, 2, null, 'The text describes the river''s pollution (problem), the factories (cause), and the cleanup (response).', 'published', 'import', now()),
('rwl2c_012', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'Some trees are deciduous; in other words, they lose all their leaves each fall and grow new ones in the spring. Oaks, maples, and birches are common examples in North America.', null, 'Which choice best describes the function of the phrase "in other words" in the text?', '["It introduces a contrasting idea", "It signals that the author is restating an idea in simpler terms", "It introduces a quotation", "It marks the end of the passage"]'::jsonb, 1, null, '"In other words" introduces a simpler restatement.', 'published', 'import', now()),
('rwl2c_013', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Graphing calculators let students explore functions quickly, freeing time to focus on understanding concepts rather than doing long calculations by hand.

Text 2
Graphing calculators are powerful, but students who type an equation incorrectly will get a confident-looking graph of the wrong function. Estimating the answer first remains an essential habit.', null, 'Based on the texts, how would the author of Text 2 most likely respond to Text 1?', '["By agreeing that the tool is useful but warning that students still need to check its answers", "By arguing that calculators should never be used", "By stating that math tests are unnecessary", "By claiming that students do not use calculators"]'::jsonb, 0, null, 'Text 2 accepts the tool''s value but adds a caution about checking.', 'published', 'import', now()),
('rwl2c_014', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Cats dropped from a height almost always land on their feet. Even cats that begin upside down manage to turn over in midair.

Text 2
Cats have very flexible spines and no fixed collarbone. As they fall, they twist the front half of their body and then the back half, rotating without anything to push against.', null, 'Which choice best describes how Text 1 and Text 2 relate to each other?', '["Text 2 denies that the observation in Text 1 occurred", "Both texts describe the same experiment", "Text 1 explains a theory that Text 2 later proves false", "Text 2 offers an explanation for the observation described in Text 1"]'::jsonb, 3, null, 'Text 1 describes the observation (cats landing on their feet); Text 2 explains how it happens.', 'published', 'import', now()),
('rwl2c_015', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'As a young writer, Octavia Butler was told by a relative that Black women could not make a living writing stories. She kept writing anyway, rising before dawn to work on novels before her day jobs. Butler went on to win the Hugo and Nebula Awards, and in 1995 she became the first science fiction writer to receive a MacArthur Fellowship.', null, 'Which choice best states the main idea of the text?', '["Octavia Butler overcame early discouragement to become an acclaimed science fiction writer", "Science fiction was not popular during the twentieth century", "Octavia Butler wrote mostly nonfiction", "Most writers are encouraged by their teachers"]'::jsonb, 0, null, 'The text traces Butler''s path from discouragement to major awards.', 'published', 'import', now()),
('rwl2c_016', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'During heavy storms, rain pours off roofs and pavement into storm drains, which can overflow and flood streets. Some cities now encourage green roofs, which are covered with soil and plants. The plants and soil soak up much of the rain, releasing it slowly and easing the burden on drains.', null, 'According to the text, why do some cities install "green roofs"?', '["To grow food for restaurants", "To make buildings taller", "To absorb rainwater and reduce flooding", "To block cell-phone signals"]'::jsonb, 2, null, 'The text says the plants soak up rain that would otherwise flood storm drains.', 'published', 'import', now()),
('rwl2c_017', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'The following text is adapted from a novel.

The new apartment smelled of fresh paint and somebody else''s cooking. Mei unpacked her books slowly, setting each one on the empty shelf as if it might not belong there. Then she noticed the window: it looked out over a small park where a girl about her age was teaching a dog to catch a frisbee. Mei watched for a long time.', null, 'Based on the text, how does the narrator feel about the move?', '["Uncertain, but beginning to feel hopeful", "Terrified of the new house", "Completely indifferent", "Furious at her parents"]'::jsonb, 0, null, 'She misses her old home but notices something she likes about the new one.', 'published', 'import', now()),
('rwl2c_018', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Traditional traffic lights change on a fixed schedule, even when no cars are waiting. In Pittsburgh, a system of adaptive signals uses cameras and radar to measure traffic at each intersection and adjusts the timing every few seconds. In early tests, the system reduced travel times by about 25 percent.', null, 'Which choice best states the main idea of the text?', '["Cities are using sensors and data to reduce traffic delays at intersections", "Most drivers ignore traffic signals", "Traffic lights are no longer needed in modern cities", "Cities are building more highways to reduce traffic"]'::jsonb, 0, null, 'The text describes adaptive signals that adjust to real-time traffic and cut delays.', 'published', 'import', now()),
('rwl2c_019', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A teacher claims that students who read more each day tend to have larger vocabularies.', '{"h": ["Daily reading", "Avg. vocabulary score"], "r": [["0–10 min", "71"], ["11–20 min", "76"], ["30 min", "82"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the claim?', '["Students who read for 30 minutes a day averaged 82 on the vocabulary test, compared with 71 for students who read for 0–10 minutes", "Students who read 30 minutes a day averaged 82 on the test", "The test had 50 questions", "Some students read every day"]'::jsonb, 0, null, 'The claim compares more reading with less reading; this choice gives both groups'' scores.', 'published', 'import', now()),
('rwl2c_020', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A town official claims that the town''s free compost program caused this year''s larger vegetable harvests in community gardens.', null, 'Which finding, if true, would most strongly weaken the claim?', '["Some gardeners prefer tomatoes to peppers", "Compost is made from food scraps", "Gardens in the town that received no compost produced just as many vegetables as those that did", "The compost program started in the spring"]'::jsonb, 2, null, 'If gardens without compost grew just as much, compost couldn''t explain the bigger harvests.', 'published', 'import', now()),
('rwl2c_021', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'In a play, the character Nora values honesty more than her own comfort.', null, 'Which quotation from the play best illustrates the claim that the character Nora values honesty above comfort?', '["\"The tea is getting cold, Nora.\"", "\"I''ll be home before the snow begins.\"", "\"Nora, you look tired this evening.\"", "\"I would rather hear a hard truth today than a kind lie every day for the rest of my life.\""]'::jsonb, 3, null, 'Only this line shows Nora choosing truth over comfort.', 'published', 'import', now()),
('rwl2c_022', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'A researcher concluded that wire cages placed over sea turtle nests help protect eggs from predators.', '{"h": ["Nest type", "Number of nests", "Hatching rate (%)"], "r": [["Caged", "100", "78"], ["Uncaged", "100", "31"]]}'::jsonb, 'Which choice best describes data from the table that support the researcher''s conclusion?', '["Both groups of nests were on the same beach", "Nests protected by wire cages had a 78 percent hatching rate, compared with 31 percent for unprotected nests", "Researchers studied 200 nests", "Unprotected nests had a 31 percent hatching rate"]'::jsonb, 1, null, 'The conclusion compares caged and uncaged nests, so both rates are needed.', 'published', 'import', now()),
('rwl2c_023', 'rw', 2, 'Information and Ideas', 'Inferences', 'Divers exploring a shipwreck off the coast of Maine recovered dozens of coins. The newest coins were minted in 1880. Because the ship must have sunk after its newest coins were made, the divers concluded that ____', null, 'Which choice most logically completes the text?', '["the coins were added to the wreck recently", "the ship was built in 1880", "the ship never carried passengers", "the shipwreck likely sank after 1880"]'::jsonb, 3, null, 'The newest coin on board was made in 1880, so the ship couldn''t have sunk before then.', 'published', 'import', now()),
('rwl2c_024', 'rw', 2, 'Information and Ideas', 'Inferences', 'Researchers recorded the songs of great tits living near a busy highway and in a quiet forest nearby. The birds near the highway sang louder and at higher pitches than the forest birds. One possible explanation is that ____', null, 'Which choice most logically completes the text?', '["the birds stopped singing completely", "roads have no effect on wildlife", "the noise from the road may affect how well the birds can hear one another", "the birds prefer to nest near roads"]'::jsonb, 2, null, 'Birds sang louder and higher near the road, suggesting traffic noise makes communication harder.', 'published', 'import', now()),
('rwl2c_025', 'rw', 2, 'Information and Ideas', 'Inferences', 'In a study, two similar groups of patients took the same blood-pressure medicine. One group took it each morning; the other took it each evening. After six months, the morning group''s blood pressure had dropped more. If the groups were otherwise alike, this suggests that ____', null, 'Which choice most logically completes the text?', '["the evening group was older", "the medicine may work better when taken in the morning", "patients forgot to take the medicine at night", "the medicine has no effect"]'::jsonb, 1, null, 'Same medicine, better results in the morning group, so timing may matter.', 'published', 'import', now()),
('rwl2c_026', 'rw', 2, 'Information and Ideas', 'Inferences', 'Several species of small land mammals found on an island are also found on the nearby mainland. None of these animals can swim long distances, and the channel between the island and the mainland is several miles wide. Geologists therefore suspect that ____', null, 'Which choice most logically completes the text?', '["the island is getting larger", "no animals live on the mainland", "the island was probably once connected to the mainland", "the animals swam to the island recently"]'::jsonb, 2, null, 'Land animals that can''t swim far live on both the island and mainland, suggesting a former land connection.', 'published', 'import', now()),
('rwl2c_027', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The students visited the Smithsonian''s National Air and Space ____ holds the Wright brothers'' 1903 flyer.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["museum. Which", "museum, which", "museum which", "museum; which"]'::jsonb, 1, null, 'The "which" clause adds extra information about the museum, so it is set off by a comma.', 'published', 'import', now()),
('rwl2c_028', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Giraffes need surprisingly little ____ a result, they often sleep for less than two hours a day, in short naps.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["sleep; as", "sleep as", "sleep: as,", "sleep, as"]'::jsonb, 0, null, 'Two complete sentences are joined with a semicolon here; a comma would create a comma splice.', 'published', 'import', now()),
('rwl2c_029', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'A day on ____ lasts longer than a year on Venus: the planet takes about 243 Earth days to spin once but only about 225 days to orbit the sun.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Venus:", "Venus;", "Venus", "Venus,"]'::jsonb, 2, null, 'No punctuation belongs between the subject "a day on Venus" and its verb "lasts."', 'published', 'import', now()),
('rwl2c_030', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'The program teaches three essential ____ first aid, map reading, and shelter building.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["skills;", "skills:", "skills", "skills,"]'::jsonb, 1, null, 'A colon introduces the list after the complete sentence.', 'published', 'import', now()),
('rwl2c_031', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Georgia O''Keeffe''s paintings of New Mexico—its red cliffs, bleached bones, and wide desert ____ made the region famous among art lovers.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["landscapes—", "landscapes;", "landscapes,", "landscapes"]'::jsonb, 0, null, 'The phrase set off by a dash must close with a dash.', 'published', 'import', now()),
('rwl2c_032', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Before the autumn ____ in the region test the sugar content of their grapes every few days.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["harvest farmers", "harvest, farmers", "harvest. Farmers,", "harvest; farmers"]'::jsonb, 1, null, 'A comma follows the introductory dependent clause "Before the harvest."', 'published', 'import', now()),
('rwl2c_033', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The museum''s collection of ancient Chinese bronze vessels ____ one of the largest outside Asia.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were", "are", "have been", "is"]'::jsonb, 3, null, 'The subject "the collection" is singular.', 'published', 'import', now()),
('rwl2c_034', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'After the storm, the volunteers spent ____ weekend clearing fallen branches from the trails.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["its", "his or her", "their", "it''s"]'::jsonb, 2, null, 'The pronoun refers to "the volunteers," which is plural.', 'published', 'import', now()),
('rwl2c_035', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Before Bessie Coleman became the first African American woman to earn a pilot''s license in 1921, she ____ aviation in France because no American flight school would accept her.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is studying", "will study", "studies", "had studied"]'::jsonb, 3, null, 'The studying happened before she became a pilot in the past, so the past perfect is used.', 'published', 'import', now()),
('rwl2c_036', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The school''s new green plan encourages students to reduce waste, to reuse materials, and ____ whenever possible.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["recycled", "recycling", "to recycle", "recycle"]'::jsonb, 2, null, 'The list is parallel: to reduce, to reuse, and to recycle.', 'published', 'import', now()),
('rwl2c_037', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'After the new bus line opened, there were ____ cars on Main Street during rush hour.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["less", "little", "lesser", "fewer"]'::jsonb, 3, null, '"Fewer" is used with countable nouns such as "cars."', 'published', 'import', now()),
('rwl2c_038', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'In the Arctic summer, the sun ____ above the horizon and stays there for weeks without setting.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have risen", "rises", "rise", "rising"]'::jsonb, 1, null, 'The subject "the sun" is singular and the statement is a general fact, so the present-tense "rises" is correct.', 'published', 'import', now()),
('rwl2c_039', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Honeybees are remarkable navigators. ____ they can communicate the exact direction and distance of a food source to other bees through a movement called the waggle dance.', null, 'Which choice completes the text with the most logical transition?', '["In fact,", "Instead,", "Otherwise,", "However,"]'::jsonb, 0, null, 'The second sentence emphasizes and strengthens the first, so "In fact" fits.', 'published', 'import', now()),
('rwl2c_040', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Solar panels produce electricity without burning fuel. ____ they generate power only when the sun is shining, so many homes also need batteries or another energy source.', null, 'Which choice completes the text with the most logical transition?', '["Therefore,", "For instance,", "On the other hand,", "Likewise,"]'::jsonb, 2, null, 'The second sentence presents a contrasting drawback.', 'published', 'import', now()),
('rwl2c_041', 'rw', 2, 'Expression of Ideas', 'Transitions', 'The volunteers first removed invasive plants from the riverbank. ____ they planted native shrubs to hold the soil in place.', null, 'Which choice completes the text with the most logical transition?', '["Similarly,", "However,", "For example,", "Afterward,"]'::jsonb, 3, null, 'The events are in time order, so "Afterward" fits.', 'published', 'import', now()),
('rwl2c_042', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Unlike most fish, seahorse males carry developing eggs in a pouch until they hatch. ____ in seahorses, it is the father, not the mother, who gives birth.', null, 'Which choice completes the text with the most logical transition?', '["Thus,", "Nonetheless,", "For instance,", "Meanwhile,"]'::jsonb, 0, null, 'The second sentence states a conclusion drawn from the first.', 'published', 'import', now()),
('rwl2c_043', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Mount Everest''s "death zone," above 26,000 feet, has so little oxygen that the human body slowly begins to fail. ____ hundreds of climbers attempt to reach the summit each year.', null, 'Which choice completes the text with the most logical transition?', '["For example,", "Even so,", "Similarly,", "As a result,"]'::jsonb, 1, null, 'Despite the danger described, people still climb, so a concession transition fits.', 'published', 'import', now()),
('rwl2c_044', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Great Chicago Fire began on October 8, 1871.
• Strong winds spread the flames.
• It burned more than three square miles in about a day and a half.
• Many of the city''s buildings were made of wood.
• Afterward, Chicago was rebuilt with more brick and stone.', null, 'The student wants to emphasize how quickly the Great Chicago Fire spread. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The Great Chicago Fire began in October 1871.", "Many buildings in Chicago were made of wood.", "Driven by strong winds, the Great Chicago Fire burned more than three square miles of the city in about a day and a half.", "After the fire, Chicago was rebuilt with more brick and stone."]'::jsonb, 2, null, 'Only this choice stresses speed: a large area burned in about a day and a half.', 'published', 'import', now()),
('rwl2c_045', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Lake Baikal is in Siberia, Russia.
• It is the deepest lake in the world, more than 5,300 feet deep.
• It holds about 20% of the world''s unfrozen surface fresh water.
• Its surface freezes in winter.
• It attracts many tourists.', null, 'The student wants to explain what makes Lake Baikal unusual. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Lake Baikal in Siberia is the world''s deepest lake and holds about one-fifth of all the unfrozen fresh water on Earth''s surface.", "Lake Baikal is located in Siberia.", "Many people visit Lake Baikal each year.", "Lake Baikal freezes in winter."]'::jsonb, 0, null, 'Only this choice gives the facts that make the lake unusual.', 'published', 'import', now()),
('rwl2c_046', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Farmers in dry regions rely on irrigation.
• Sprinkler systems spray water over an entire field.
• Drip irrigation delivers water directly to plant roots through tubes.
• Drip irrigation uses 30 to 50 percent less water than sprinklers.
• Modern drip irrigation was developed in Israel.', null, 'The student wants to compare the two methods. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Drip irrigation was developed in Israel.", "Sprinklers are common on farms.", "Farmers use irrigation in dry regions.", "Drip irrigation delivers water directly to plant roots and uses 30 to 50 percent less water than sprinkler systems, which spray water over the whole field."]'::jsonb, 3, null, 'Only this choice compares how the methods work and how much water each uses.', 'published', 'import', now()),
('mathl1c_001', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 7x − 3 = 32, what is the value of x?', '["4.1", "35", "5", "4"]'::jsonb, 2, null, 'Add 3: 7x = 35. Divide by 7: x = 5.', 'published', 'import', now()),
('mathl1c_002', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 3(x + 4) = 27, what is the value of x?', null, null, '["5"]'::jsonb, 'Divide by 3: x + 4 = 9, so x = 5.', 'published', 'import', now()),
('mathl1c_003', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 20 − x = 13, what is the value of x?', '["7", "13", "33", "−7"]'::jsonb, 0, null, 'Subtract 20: −x = −7, so x = 7.', 'published', 'import', now()),
('mathl1c_004', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If x/5 = 8, what is the value of x?', '["3", "1.6", "40", "13"]'::jsonb, 2, null, 'Multiply both sides by 5: x = 40.', 'published', 'import', now()),
('mathl1c_005', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'Ava is 4 years older than twice her brother''s age. Ava is 18. How old is her brother?', '["7", "5", "11", "9"]'::jsonb, 0, null, '2b + 4 = 18, so 2b = 14 and b = 7.', 'published', 'import', now()),
('mathl1c_006', 'math', 1, 'Algebra', 'Linear functions', null, null, 'The function f is defined by f(x) = 6x − 5. What is f(3)?', '["13", "1", "23", "18"]'::jsonb, 0, null, 'f(3) = 18 − 5 = 13.', 'published', 'import', now()),
('mathl1c_007', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A line passes through (0, 1) and (3, 7). What is its slope?', null, null, '["2"]'::jsonb, 'Slope = (7 − 1) ÷ (3 − 0) = 2.', 'published', 'import', now()),
('mathl1c_008', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A plant is 4 cm tall and grows 1.5 cm each week. Which expression gives its height after w weeks?', '["4w − 1.5", "5.5w", "4 + 1.5w", "1.5 + 4w"]'::jsonb, 2, null, 'Start at 4 cm and add 1.5 cm for each week.', 'published', 'import', now()),
('mathl1c_009', 'math', 1, 'Algebra', 'Linear functions', null, null, 'What is the y-intercept of the line y = 5x − 2?', '["(−2, 0)", "(2, 0)", "(0, 5)", "(0, −2)"]'::jsonb, 3, null, 'In y = mx + b, the y-intercept is (0, b) = (0, −2).', 'published', 'import', now()),
('mathl1c_010', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A parking garage charges $3 plus $2 for each hour. Kim paid $13. How many hours did she park?', '["4", "5", "6.5", "8"]'::jsonb, 1, null, '3 + 2h = 13, so h = 5.', 'published', 'import', now()),
('mathl1c_011', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'x + y = 15
x − y = 3

What is the value of x?', '["6", "9", "7.5", "12"]'::jsonb, 1, null, 'Add the equations: 2x = 18, so x = 9.', 'published', 'import', now()),
('mathl1c_012', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'y = 4x
x + y = 25

What is the value of x?', null, null, '["5"]'::jsonb, 'x + 4x = 25, so 5x = 25 and x = 5.', 'published', 'import', now()),
('mathl1c_013', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'Pencils cost $1 and erasers cost $2. Leo buys 9 items for $13. How many erasers does he buy?', '["3", "5", "4", "6"]'::jsonb, 2, null, 'p + e = 9 and p + 2e = 13. Subtracting: e = 4.', 'published', 'import', now()),
('mathl1c_014', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Which value of x is a solution to 4x ≤ 20?', '["20", "6", "7", "5"]'::jsonb, 3, null, '4x ≤ 20 means x ≤ 5. Only 5 works.', 'published', 'import', now()),
('mathl1c_015', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'A box can hold at most 30 pounds. Each book weighs 2 pounds. What is the greatest number of books the box can hold?', null, null, '["15"]'::jsonb, '2b ≤ 30, so b ≤ 15.', 'published', 'import', now()),
('mathl1c_016', 'math', 1, 'Algebra', 'Linear inequalities', null, null, 'Which inequality means "x is more than 12"?', '["x ≥ 12", "x > 12", "x < 12", "x ≤ 12"]'::jsonb, 1, null, '"More than" means greater than, without equality.', 'published', 'import', now()),
('mathl1c_017', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 4(2x + 3) − 5?', '["8x + 7", "8x − 2", "8x + 17", "6x + 7"]'::jsonb, 0, null, '8x + 12 − 5 = 8x + 7.', 'published', 'import', now()),
('mathl1c_018', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to x^{4} · x^{4}?', '["x^{8}", "2x^{4}", "x^{0}", "x^{16}"]'::jsonb, 0, null, 'Add the exponents: 4 + 4 = 8.', 'published', 'import', now()),
('mathl1c_019', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 3x(x − 2)?', '["3x^{2} − 2", "x^{2} − 6x", "3x − 6x", "3x^{2} − 6x"]'::jsonb, 3, null, 'Multiply 3x by each term: 3x^{2} − 6x.', 'published', 'import', now()),
('mathl1c_020', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 10x^{3} ÷ 2x?', '["5x^{2}", "20x^{4}", "5x^{3}", "8x^{2}"]'::jsonb, 0, null, '10 ÷ 2 = 5 and x^{3} ÷ x = x^{2}.', 'published', 'import', now()),
('mathl1c_021', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'If x^{2} = 81 and x < 0, what is the value of x?', '["9", "−81", "−9", "−40.5"]'::jsonb, 2, null, 'x^{2} = 81 gives x = 9 or −9. Since x < 0, x = −9.', 'published', 'import', now()),
('mathl1c_022', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'If 2x^{2} = 32 and x > 0, what is x?', null, null, '["4"]'::jsonb, 'x^{2} = 16, so x = 4.', 'published', 'import', now()),
('mathl1c_023', 'math', 1, 'Advanced Math', 'Nonlinear equations', null, null, 'What are the solutions to (x + 3)(x − 7) = 0?', '["x = 4 and x = 21", "x = −3 and x = 7", "x = −3 only", "x = 3 and x = −7"]'::jsonb, 1, null, 'Each factor can be 0: x = −3 or x = 7.', 'published', 'import', now()),
('mathl1c_024', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'The function g is defined by g(x) = x^{2} − 3. What is g(5)?', '["22", "7", "28", "25"]'::jsonb, 0, null, 'g(5) = 25 − 3 = 22.', 'published', 'import', now()),
('mathl1c_025', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'A savings account starts with $100 and doubles every 8 years. How much is in the account after 16 years?', '["1,600", "200", "400", "300"]'::jsonb, 2, null, '16 years is two doublings: 100 → 200 → 400.', 'published', 'import', now()),
('mathl1c_026', 'math', 1, 'Advanced Math', 'Nonlinear functions', null, null, 'Which point is on the graph of y = x^{2}?', '["(−3, 9)", "(3, 6)", "(9, 3)", "(−3, −9)"]'::jsonb, 0, null, '(−3)^{2} = 9, so (−3, 9) is on the graph.', 'published', 'import', now()),
('mathl1c_027', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A car uses 3 gallons of gas to travel 96 miles. How many miles can it travel on 5 gallons?', '["288", "128", "150", "160"]'::jsonb, 3, null, '96 ÷ 3 = 32 miles per gallon. 32 × 5 = 160.', 'published', 'import', now()),
('mathl1c_028', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'The ratio of cats to dogs at a shelter is 2 : 3. There are 18 dogs. How many cats are there?', null, null, '["12"]'::jsonb, '2/3 = c/18, so c = 12.', 'published', 'import', now()),
('mathl1c_029', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A worker earns $18 per hour. How much does the worker earn for 7.5 hours?', '["126", "144", "135", "25.5"]'::jsonb, 2, null, '18 × 7.5 = 135.', 'published', 'import', now()),
('mathl1c_030', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'How many centimeters are in 3.2 meters? (1 meter = 100 centimeters)', '["0.032", "32", "3,200", "320"]'::jsonb, 3, null, '3.2 × 100 = 320.', 'published', 'import', now()),
('mathl1c_031', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'What is 25% of 84?', '["63", "21", "16", "25"]'::jsonb, 1, null, '84 ÷ 4 = 21.', 'published', 'import', now()),
('mathl1c_032', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A $50 pair of shoes is on sale for 30% off. What is the sale price, in dollars?', null, null, '["35"]'::jsonb, '30% of 50 is 15, so the sale price is 50 − 15 = 35.', 'published', 'import', now()),
('mathl1c_033', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, '15 is 60% of what number?', '["75", "21", "9", "25"]'::jsonb, 3, null, '0.60 × n = 15, so n = 25.', 'published', 'import', now()),
('mathl1c_034', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'What is the mean of 12, 15, 18, 21, and 24?', '["17", "15", "90", "18"]'::jsonb, 3, null, 'The sum is 90, and 90 ÷ 5 = 18.', 'published', 'import', now()),
('mathl1c_035', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'What is the median of 3, 11, 6, 9, 2, 8?', '["6.5", "6", "7", "8"]'::jsonb, 2, null, 'In order: 2, 3, 6, 8, 9, 11. The middle two are 6 and 8, so the median is 7.', 'published', 'import', now()),
('mathl1c_036', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'Test scores in a group were 70, 85, 85, 90, and 95. What is the mode?', null, null, '["85"]'::jsonb, '85 appears twice, more than any other score.', 'published', 'import', now()),
('mathl1c_037', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, '{"h": ["T-shirts", "Cost ($)"], "r": [["2", "16"], ["3", "24"], ["5", "40"]]}'::jsonb, 'The table shows the cost of buying T-shirts. What is the cost of 6 T-shirts, in dollars?', '["40", "48", "54", "42"]'::jsonb, 1, null, 'Each T-shirt costs $8 (16 ÷ 2). 6 × 8 = 48.', 'published', 'import', now()),
('mathl1c_038', 'math', 1, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'As a car gets older, its value tends to go down. What kind of association is this?', '["Positive", "No association", "Negative", "Constant"]'::jsonb, 2, null, 'One variable increases (age) while the other decreases (value): a negative association.', 'published', 'import', now()),
('mathl1c_039', 'math', 1, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'A spinner has 5 equal sections colored red, blue, green, yellow, and purple. What is the probability of landing on blue?', '["1/5", "4/5", "1/4", "2/5"]'::jsonb, 0, null, 'One of 5 equal sections is blue.', 'published', 'import', now()),
('mathl1c_040', 'math', 1, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'There are 12 boys and 18 girls in a class. A student is chosen at random. What is the probability the student is a boy?', '["2/3", "3/5", "2/5", "1/3"]'::jsonb, 2, null, '12 out of 30 students are boys: 12/30 = 2/5.', 'published', 'import', now()),
('mathl1c_041', 'math', 1, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A random sample of 60 shoppers found that 45 paid with a card. About what percent of all shoppers pay with a card?', '["25%", "75%", "60%", "45%"]'::jsonb, 1, null, '45 ÷ 60 = 0.75 = 75%.', 'published', 'import', now()),
('mathl1c_042', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangle is 15 m long and 6 m wide. What is its perimeter, in meters?', '["90", "42", "36", "21"]'::jsonb, 1, null, '2(15 + 6) = 42.', 'published', 'import', now()),
('mathl1c_043', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A rectangular box is 6 in long, 4 in wide, and 2 in tall. What is its volume, in cubic inches?', null, null, '["48"]'::jsonb, '6 × 4 × 2 = 48.', 'published', 'import', now()),
('mathl1c_044', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A triangle has a base of 14 cm and a height of 9 cm. What is its area, in square centimeters?', '["46", "23", "126", "63"]'::jsonb, 3, null, '½ × 14 × 9 = 63.', 'published', 'import', now()),
('mathl1c_045', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two angles of a triangle are 90° and 35°. What is the third angle?', '["45°", "55°", "35°", "125°"]'::jsonb, 1, null, '180 − 90 − 35 = 55.', 'published', 'import', now()),
('mathl1c_046', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two angles are supplementary. One measures 120°. What is the other?', '["240°", "60°", "30°", "40°"]'::jsonb, 1, null, 'Supplementary angles add to 180°: 180 − 120 = 60.', 'published', 'import', now()),
('mathl1c_047', 'math', 1, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A right triangle has legs of 9 and 12. What is the hypotenuse?', null, null, '["15"]'::jsonb, '√(81 + 144) = √225 = 15.', 'published', 'import', now()),
('mathl1c_048', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A bicycle wheel has a diameter of 26 inches. How far does the bicycle move in one full turn of the wheel?', '["26π inches", "169π inches", "52π inches", "13π inches"]'::jsonb, 0, null, 'One full turn covers the wheel''s circumference: C = πd = 26π inches.', 'published', 'import', now()),
('mathl1c_049', 'math', 1, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has an area of 25π. What is its radius?', '["25", "12.5", "625", "5"]'::jsonb, 3, null, 'πr^{2} = 25π, so r^{2} = 25 and r = 5.', 'published', 'import', now())
